/**
 * Stage 1 of `buildTheme`: the named base theme, with the residual summary of
 * a theme that ships in a registered package (#180).
 *
 * `BUILTIN_THEMES` (`themes-builtin.ts`, generated by `scripts/compile-themes.py`)
 * holds, per core theme, the json-family colours an executed `!theme` does not
 * reach yet. A theme #180 moved out of core carries that residue in its
 * package instead (`PackagedTheme.residue`), so it leaves `dist/` with the
 * theme (plans/themes-opt-in-packages/decisions.md D4). Kept out of `theme.ts`
 * (at the 500-line limit) and `build-theme.ts`.
 */
import { deepMergeTheme, defaultTheme, resolveTheme, type Theme } from './theme.js';
import { BUILTIN_THEMES } from './themes-builtin.js';
import type { IncludeStore } from './tim/IncludeStore.js';

/**
 * `resolveTheme(themeName)`, except that a name core has no residue for reads
 * the registered package's residue, merged onto `defaultTheme` as
 * `resolveTheme` merges a core one (`theme.ts`, `resolveTheme`).
 */
export function resolveBaseTheme(themeName: string, store: IncludeStore | undefined): Theme {
  const residue = Object.hasOwn(BUILTIN_THEMES, themeName) ? undefined : store?.getPackagedTheme?.(themeName)?.residue;
  return residue === undefined ? resolveTheme(themeName) : deepMergeTheme(defaultTheme, residue);
}
